package ru.neverland.townyjustice;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;
import com.palmergames.bukkit.towny.TownyAPI;
import ru.neverland.core.*;
import static ru.neverland.townyjustice.JusticeDossiers.*;

/** Optional private evidence/review workflow, completely separate from financial and custody transitions. */
public final class JusticeDossiersService {
    public record View(JusticeCase original,Dossier dossier,boolean available,String issue){}
    private record Cached(Map<String,Object> value,long at){}
    private final JavaPlugin plugin;private final JusticeService justice;private final JusticeDossiersRepository repository;
    private volatile boolean closed;private volatile Map<UUID,Cached> reports=Map.of();private final AtomicReference<Map<UUID,Long>> interest=new AtomicReference<>(Map.of());
    public JusticeDossiersService(JavaPlugin plugin,JusticeService justice,JusticeDossiersRepository repository){this.plugin=plugin;this.justice=justice;this.repository=repository;}
    private boolean enabled(){return Boolean.TRUE.equals(plugin.getConfig().get("reviews.enabled",true));}
    private boolean participant(Player actor,JusticeCase c,Dossier d){if(c.subject().equals(actor.getUniqueId())||justice.manager(actor,c.town()))return true;var resident=TownyAPI.getInstance().getResident(actor.getUniqueId());return actor.getUniqueId().equals(d.assigned())&&resident!=null&&resident.getTownOrNull()!=null&&resident.getTownOrNull().getUUID().equals(c.town());}
    public boolean readable(Player actor,JusticeCase c){try(var guard=SuiteState.guard()){var d=repository.state().dossiers().getOrDefault(c.id(),Dossier.empty(c.id(),c.town(),c.subject()));return actor.hasPermission("neverlandtownyjustice.use")&&participant(actor,c,d);}}
    private Dossier dossier(JusticeCase c){var d=repository.state().dossiers().getOrDefault(c.id(),Dossier.empty(c.id(),c.town(),c.subject()));if(!d.town().equals(c.town())||!d.subject().equals(c.subject()))throw new IllegalArgumentException("Журнал относится к другим участникам; требуется проверка администратора");return d;}
    private JusticeCase access(Player actor,UUID id,boolean manager){if(closed||!enabled()||!repository.writable())throw new IllegalArgumentException("Разбирательства сейчас недоступны. Штрафы, сроки и платежи не изменены.");var c=justice.get(id);if(!actor.hasPermission("neverlandtownyjustice.use")||!(manager?justice.manager(actor,c.town()):participant(actor,c,dossier(c))))throw new IllegalArgumentException("Нет доступа к материалам этого дела");return c;}
    private CompletionStage<String> save(Player actor,JusticeCase before,State expected,Dossier next,boolean manager,String message){var current=access(actor,before.id(),manager);if(!current.equals(before))throw new IllegalArgumentException("Дело изменилось; откройте его заново");var previous=expected.dossiers().get(before.id());if(next.assigned()!=null&&(previous==null||!next.assigned().equals(previous.assigned()))){var target=TownyAPI.getInstance().getResident(next.assigned());if(target==null||target.getTownOrNull()==null||!target.getTownOrNull().getUUID().equals(before.town()))throw new IllegalArgumentException("Ответственный больше не состоит в городе");}var stage=repository.commit(expected,expected.put(next));stage.whenComplete((saved,error)->{if(closed||!plugin.isEnabled()||org.bukkit.Bukkit.isStopping())return;SuiteScheduler.get().runTask(plugin,()->{var fresh=new HashMap<>(reports);fresh.remove(before.id());reports=Map.copyOf(fresh);});});return stage.thenApply(saved->message);}
    public CompletionStage<String> assign(Player actor,UUID id,UUID resident)throws Exception{try(var guard=SuiteState.guard()){var c=access(actor,id,true);var target=TownyAPI.getInstance().getResident(resident);if(target==null||target.getTownOrNull()==null||!target.getTownOrNull().getUUID().equals(c.town()))throw new IllegalArgumentException("Ответственный должен быть жителем города дела");var before=repository.state();return save(actor,c,before,dossier(c).assign(actor.getUniqueId(),resident,System.currentTimeMillis()),true,"Ответственный сохранён. Назначение не даёт права выносить решение или штрафовать.");}}
    public CompletionStage<String> note(Player actor,UUID id,String text)throws Exception{try(var guard=SuiteState.guard()){var c=access(actor,id,false);var before=repository.state();var next=dossier(c).add(Evidence.note(c.id(),actor.getUniqueId(),text,System.currentTimeMillis()));return save(actor,c,before,next,false,"Сведения сохранены. Это не установление виновности и не новое взыскание.");}}
    public CompletionStage<String> incident(Player actor,UUID id,UUID incident)throws Exception{try(var guard=SuiteState.guard()){var c=access(actor,id,false);Map<?,?> data;try{var api=ApiServices.require("NeverLandTownyCrime","ru.neverland.townycrime.api.TownyCrimeApi","incidentEvidence");data=(Map<?,?>)((Optional<?>)api.invoke("incidentEvidence",new Class<?>[]{UUID.class},incident)).orElseThrow();}catch(ReflectiveOperationException|RuntimeException|LinkageError error){throw new IllegalArgumentException("Подтверждённые сведения о происшествии временно недоступны",error);}
        if(!incident.toString().equals(data.get("id"))||!("crime:"+incident).equals(data.get("sourceId"))||!c.town().toString().equals(data.get("town"))||!Set.of("APPLIED","CLOSED").contains(data.get("phase")))throw new IllegalArgumentException("Происшествие не подтверждено или относится к другому городу");if(!(data.get("kind")instanceof String kind)||!(data.get("resource")instanceof String resource)||!"CITY".equals(data.get("scope"))||!"THOUSANDTH_RESOURCE".equals(data.get("amountUnit")))throw new IllegalArgumentException("Неверный формат сведений о происшествии");if(!Set.of("BURGLARY","EXTORTION").contains(kind)||!(data.get("amount") instanceof Long amount)||amount<0||amount>1_000_000_000L||!(data.get("created")instanceof Long created)||created<0||resource.length()>64||kind.equals("BURGLARY")&&(!Set.of("wood","stone","metal","materials","food","water","knowledge","influence").contains(resource)||amount<1)||kind.equals("EXTORTION")&&(!resource.isEmpty()||amount!=0))throw new IllegalArgumentException("Не удалось проверить сведения о происшествии");
        String details=(kind.equals("BURGLARY")?"Кража со склада":"Вымогательство")+"; ресурс: "+(resource.isEmpty()?"не указан":resourceName(resource))+"; количество: "+java.math.BigDecimal.valueOf(amount,3).stripTrailingZeros().toPlainString()+"; дата: "+java.time.format.DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm").withZone(java.time.ZoneId.of("Europe/Moscow")).format(java.time.Instant.ofEpochMilli(created))+" МСК"+". Место внутри города и виновник системой не установлены.";var before=repository.state();var evidence=new Evidence("crime:"+incident,actor.getUniqueId(),System.currentTimeMillis(),"CRIME",incident.toString(),details);return save(actor,c,before,dossier(c).add(evidence),false,"Происшествие связано с делом. Связь не подтверждает виновность участника.");}}
    private static String resourceName(String id){return switch(id){case "wood"->"Древесина";case "stone"->"Камень";case "metal"->"Металл";case "materials"->"Стройматериалы";case "food"->"Продовольствие";case "water"->"Вода";case "knowledge"->"Знания";case "influence"->"Влияние";default->id;};}
    public CompletionStage<String> appeal(Player actor,UUID id,String reason)throws Exception{try(var guard=SuiteState.guard()){var c=access(actor,id,false);if(!c.subject().equals(actor.getUniqueId()))throw new IllegalArgumentException("Апелляцию может подать только участник, которому назначено взыскание");var before=repository.state();return save(actor,c,before,dossier(c).appeal(actor.getUniqueId(),reason,System.currentTimeMillis()),false,"Апелляция сохранена и ожидает независимого рассмотрения. Действующие сроки и взыскание пока не изменены.");}}
    public CompletionStage<String> decide(Player actor,UUID id,Outcome result,String reason)throws Exception{try(var guard=SuiteState.guard()){var c=access(actor,id,true);if(c.subject().equals(actor.getUniqueId())||c.issuer().equals(actor.getUniqueId()))throw new IllegalArgumentException("Нужен другой уполномоченный суда: участник и автор взыскания не рассматривают собственное дело");var before=repository.state();return save(actor,c,before,dossier(c).decide(actor.getUniqueId(),result,reason,System.currentTimeMillis()),true,result==Outcome.RECONSIDER?"Решение о пересмотре сохранено. Для отмены взыскания или освобождения уполномоченный отдельно выполняет cancel или release; деньги автоматически не переводятся.":"Решение по апелляции сохранено. Исходное взыскание оставлено без изменения.");}}
    public View view(Player actor,UUID id){try(var guard=SuiteState.guard()){var c=justice.get(id);if(!readable(actor,c))throw new IllegalArgumentException("Материалы доступны участнику, ответственному жителю и уполномоченным суда");var d=dossier(c);boolean available=!closed&&enabled()&&repository.readable();watch(id);capture(id);return new View(c,d,available,available?"":"Материалы временно недоступны. Исходное дело сохранено.");}}
    public List<JusticeCase> cases(Player actor){try(var guard=SuiteState.guard()){if(!actor.hasPermission("neverlandtownyjustice.use"))throw new IllegalArgumentException("Нет доступа к суду");return justice.repository().state().cases().values().stream().filter(c->readable(actor,c)).sorted(Comparator.comparingLong(JusticeCase::created).reversed().thenComparing(JusticeCase::id)).toList();}}
    private void watch(UUID id){long now=System.nanoTime();while(true){var old=interest.get();var next=new HashMap<>(old);next.entrySet().removeIf(e->now-e.getValue()>120_000_000_000L);if(next.size()>=128&&!next.containsKey(id))next.remove(next.entrySet().stream().min(Map.Entry.comparingByValue()).orElseThrow().getKey());next.put(id,now);if(interest.compareAndSet(old,Map.copyOf(next)))return;}}
    /** Public operational status only. Evidence, appeal text, parties and private history never cross this API. */
    public Map<String,Object> status(UUID id){if(id==null||closed)return Map.of("available",false,"pending",false);watch(id);var value=reports.get(id);return value==null||System.nanoTime()-value.at()>120_000_000_000L?Map.of("available",false,"pending",true):value.value();}
    private void capture(UUID id){Map<String,Object> value=Map.of("available",false,"pending",false);if(!closed&&enabled()&&repository.readable()){var c=justice.repository().state().cases().get(id);if(c!=null){var d=dossier(c);value=Map.of("available",true,"pending",false,"revision",d.revision(),"evidenceCount",d.evidence().size(),"openAppeal",d.appeals().stream().anyMatch(a->a.outcome()==Outcome.OPEN),"decision",d.appeals().isEmpty()?"NONE":d.appeals().get(d.appeals().size()-1).outcome().name(),"sentencePhase",c.phase().name());}}var next=new HashMap<>(reports);next.keySet().retainAll(interest.get().keySet());next.put(id,new Cached(value,System.nanoTime()));reports=Map.copyOf(next);}
    public void tick(){if(closed)return;long now=System.nanoTime();for(var entry:interest.get().entrySet())if(now-entry.getValue()<120_000_000_000L)capture(entry.getKey());}
    public CompletionStage<Void> prepareClose(){closed=true;reports=Map.of();interest.set(Map.of());return repository.prepareClose();}public void awaitClosed(){repository.awaitClosed();}
}
